const c1pos=[], c3pos=[];
for(const x of [-3.5,0.5]) for(const z of [-3,-1,1,3]) c1pos.push([x,z]);
const c1={};
for(const [x,z] of c1pos){ c1[x+','+z]=anchor('3001',0,x,z); }
// course 2: rot90, 2 wide in x, 4 long in z
const c2={};
for(const x of [-4.5,-2.5,-0.5,1.5]) for(const z of [-2,2]){
  const bx = x<-1.5 ? -3.5 : 0.5;
  const bz = z<0 ? -3 : 1;
  const base = c1[bx+','+bz];
  const r = on('3001',0,base,x-bx,z-bz,90);
  if(r<0) log('c2 fail '+x+','+z); else c2[x+','+z]=r;
}
// course 3: same layout as c1
const c3={};
for(const [x,z] of c1pos){
  const bx = x<-1.5 ? -4.5 : 1.5;
  const bz = z<0 ? -2 : 2;
  const base = c2[bx+','+bz];
  const r = on('3001',0,base,x-bx,z-bz,0);
  if(r<0) log('c3 fail '+x+','+z); else c3[x+','+z]=r;
}
// trim: dark grey plates
for(const [x,z] of c1pos){ const r=on('3020',72,c3[x+','+z],0,0,0); if(r<0) log('trim fail '+x+','+z); }
